import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import path from 'node:path';

// The whole "database": one JSON array on disk. BOOKS_FILE is here so the tests can
// point at a temp file instead of the real one.
const dataFile = () =>
  process.env.BOOKS_FILE ?? path.join(process.cwd(), 'data', 'books.json');

export const READING = 'reading';
export const FINISHED = 'finished';

// Every write goes through this promise chain. Two requests arriving at once would
// otherwise both read the old array and the second would clobber the first.
let writeQueue = Promise.resolve();

function serialize(task) {
  const result = writeQueue.then(task, task);
  writeQueue = result.then(
    () => undefined,
    () => undefined
  );
  return result;
}

async function readAll() {
  try {
    const parsed = JSON.parse(await readFile(dataFile(), 'utf8'));
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    // No file yet (first run) is normal — that's an empty shelf.
    if (err.code === 'ENOENT') return [];
    throw err;
  }
}

async function writeAll(books) {
  const file = dataFile();
  await mkdir(path.dirname(file), { recursive: true });
  // Write-then-rename: a crash mid-write leaves the old file intact rather than a
  // half-written one, and readers never see a partial array.
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`);
  await rename(tmp, file);
}

/** Newest first, so the last book you added is at the top of each list. */
function byNewest(a, b) {
  return (b.addedAt ?? '').localeCompare(a.addedAt ?? '');
}

export async function listBooks() {
  const books = (await readAll()).sort(byNewest);
  return {
    reading: books.filter((b) => b.status !== FINISHED),
    finished: books.filter((b) => b.status === FINISHED),
  };
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((b) => b.id === id) ?? null;
}

export function addBook({ title, author, notes }) {
  const cleanTitle = (title ?? '').trim();
  if (!cleanTitle) throw new Error('A book needs a title.');

  return serialize(async () => {
    const books = await readAll();
    const book = {
      id: randomUUID(),
      title: cleanTitle,
      author: (author ?? '').trim(),
      notes: (notes ?? '').trim(),
      status: READING,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    await writeAll([...books, book]);
    return book;
  });
}

export function finishBook(id) {
  return updateBook(id, (book) => ({
    ...book,
    status: FINISHED,
    finishedAt: new Date().toISOString(),
  }));
}

export function saveNotes(id, notes) {
  return updateBook(id, (book) => ({ ...book, notes: (notes ?? '').trim() }));
}

function updateBook(id, change) {
  return serialize(async () => {
    const books = await readAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) return null;

    const updated = change(books[index]);
    const next = [...books];
    next[index] = updated;
    await writeAll(next);
    return updated;
  });
}

